export type Row = Record<string, string | number>;
export type Metric = { label: string; field?: string; operation: 'sum' | 'average' | 'count' | 'ratio'; denominator?: string; format?: 'currency' | 'percent' | 'number' };
export type DomainChart = { title: string; question: string; kind: 'area' | 'line' | 'columns' | 'bars' | 'donut' | 'heatmap' | 'scatter' | 'lollipop' | 'treemap' | 'rank'; dimension: string; metric: Metric; x?: string; secondary?: string; wide?: boolean };
export interface DomainSpec { title: string; subtitle: string; grain: string; color: string; tint: string; layout: string; filter: string; date: string; primary: string; category: string; metrics: Metric[]; charts: DomainChart[] }
const sum = (label: string, field: string, format: Metric['format'] = 'number'): Metric => ({ label, field, operation:'sum', format });
const avg = (label: string, field: string, format: Metric['format'] = 'number'): Metric => ({ label, field, operation:'average', format });
const ratio = (label: string, field: string, denominator: string): Metric => ({ label, field, denominator, operation:'ratio', format:'percent' });
const count = (label: string): Metric => ({ label, operation:'count' });
const chart = (kind: DomainChart['kind'], title: string, dimension: string, metric: Metric, question: string, extra: Partial<DomainChart> = {}): DomainChart => ({ kind, title, dimension, metric, question, ...extra });
