export function metricValue(rows: Row[], metric: Metric): number {
 if (metric.operation === 'count') return rows.length;
 const values = rows.map(r => r[metric.field!]).filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
 const total = values.reduce((a,b)=>a+b,0);
 if (metric.operation === 'average') return values.length ? total / values.length : 0;
 if (metric.operation === 'ratio') { const denominator = rows.reduce((s,r)=>s+Number(r[metric.denominator!] || 0),0); return denominator ? total/denominator : 0; }
 return total;
}
export function groupRows(rows: Row[], dimension: string, metric: Metric, date = false) {
 const groups = new Map<string,Row[]>();
 rows.forEach(r=>{ const label = date ? String(r[dimension]).slice(0,7) : String(r[dimension]); const group = groups.get(label)||[]; group.push(r); groups.set(label,group); });
 const result = [...groups].map(([label,group])=>({label,value:metricValue(group,metric),count:group.length}));
 return date ? result.sort((a,b)=>a.label.localeCompare(b.label)) : result.sort((a,b)=>b.value-a.value);
}
export function formatMetric(value: number, metric: Metric, currency='USD', compact=false) {
 return new Intl.NumberFormat('en-US',{maximumFractionDigits:metric.format==='percent'?1:compact?1:2, ...(compact ? {notation:'compact' as const}:{}), ...(metric.format==='percent'?{style:'percent' as const}:metric.format==='currency'?{style:'currency' as const,currency}: {})}).format(value);
}
